def test_list_spaces_pager(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_spaces), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            catalog_management_messages.ListSpacesResponse(
                spaces=[
                    catalog_management.Space(),
                    catalog_management.Space(),
                    catalog_management.Space(),
                ],
                next_page_token="abc",
            ),
            catalog_management_messages.ListSpacesResponse(
                spaces=[],
                next_page_token="def",
            ),
            catalog_management_messages.ListSpacesResponse(
                spaces=[
                    catalog_management.Space(),
                ],
                next_page_token="ghi",
            ),
            catalog_management_messages.ListSpacesResponse(
                spaces=[
                    catalog_management.Space(),
                    catalog_management.Space(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_spaces(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, catalog_management.Space) for i in results)


