def test_create_application_template_flattened():
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.create_application_template), "__call__"
    ) as call:
        # Designate an appropriate return value for the call.
        call.return_value = authoring.ApplicationTemplate()
        # Call the method with a truthy value for each flattened field,
        # using the keyword arguments to the method.
        client.create_application_template(
            parent="parent_value",
            application_template=authoring.ApplicationTemplate(name="name_value"),
            application_template_id="application_template_id_value",
        )

        # Establish that the underlying call was made with the expected
        # request object values.
        assert len(call.mock_calls) == 1
        _, args, _ = call.mock_calls[0]
        arg = args[0].parent
        mock_val = "parent_value"
        assert arg == mock_val
        arg = args[0].application_template
        mock_val = authoring.ApplicationTemplate(name="name_value")
        assert arg == mock_val
        arg = args[0].application_template_id
        mock_val = "application_template_id_value"
        assert arg == mock_val


