def test_create_component_flattened():
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.create_component), "__call__") as call:
        # Designate an appropriate return value for the call.
        call.return_value = authoring.Component()
        # Call the method with a truthy value for each flattened field,
        # using the keyword arguments to the method.
        client.create_component(
            parent="parent_value",
            component=authoring.Component(name="name_value"),
            component_id="component_id_value",
        )

        # Establish that the underlying call was made with the expected
        # request object values.
        assert len(call.mock_calls) == 1
        _, args, _ = call.mock_calls[0]
        arg = args[0].parent
        mock_val = "parent_value"
        assert arg == mock_val
        arg = args[0].component
        mock_val = authoring.Component(name="name_value")
        assert arg == mock_val
        arg = args[0].component_id
        mock_val = "component_id_value"
        assert arg == mock_val


