def test_list_connections_pager(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_connections), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            authoring_messages.ListConnectionsResponse(
                connections=[
                    authoring.Connection(),
                    authoring.Connection(),
                    authoring.Connection(),
                ],
                next_page_token="abc",
            ),
            authoring_messages.ListConnectionsResponse(
                connections=[],
                next_page_token="def",
            ),
            authoring_messages.ListConnectionsResponse(
                connections=[
                    authoring.Connection(),
                ],
                next_page_token="ghi",
            ),
            authoring_messages.ListConnectionsResponse(
                connections=[
                    authoring.Connection(),
                    authoring.Connection(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_connections(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, authoring.Connection) for i in results)


