def test_list_shares_pager(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_shares), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            sharing_messages.ListSharesResponse(
                shares=[
                    sharing.Share(),
                    sharing.Share(),
                    sharing.Share(),
                ],
                next_page_token="abc",
            ),
            sharing_messages.ListSharesResponse(
                shares=[],
                next_page_token="def",
            ),
            sharing_messages.ListSharesResponse(
                shares=[
                    sharing.Share(),
                ],
                next_page_token="ghi",
            ),
            sharing_messages.ListSharesResponse(
                shares=[
                    sharing.Share(),
                    sharing.Share(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_shares(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, sharing.Share) for i in results)


