def test_list_shared_templates_pager(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_shared_templates), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                ],
                next_page_token="abc",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[],
                next_page_token="def",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                ],
                next_page_token="ghi",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_shared_templates(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, sharing.SharedTemplate) for i in results)


def test_list_shared_templates_pages(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_shared_templates), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                ],
                next_page_token="abc",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[],
                next_page_token="def",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                ],
                next_page_token="ghi",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                ],
            ),
            RuntimeError,
        )
        pages = list(client.list_shared_templates(request={}).pages)
        for page_, token in zip(pages, ["abc", "def", "ghi", ""]):
            assert page_.raw_page.next_page_token == token


@pytest.mark.asyncio
async def test_list_shared_templates_async_pager():
    client = DesignCenterAsyncClient(
        credentials=async_anonymous_credentials(),
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_shared_templates),
        "__call__",
        new_callable=mock.AsyncMock,
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                ],
                next_page_token="abc",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[],
                next_page_token="def",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                ],
                next_page_token="ghi",
            ),
            sharing_messages.ListSharedTemplatesResponse(
                shared_templates=[
                    sharing.SharedTemplate(),
                    sharing.SharedTemplate(),
                ],
            ),
            RuntimeError,
        )
        async_pager = await client.list_shared_templates(
            request={},
        )
        assert async_pager.next_page_token == "abc"
        assert str(async_pager).startswith(f"{async_pager.__class__.__name__}<")

        responses = []
        async for response in async_pager:  # pragma: no branch
            responses.append(response)

        assert len(responses) == 6
        assert all(isinstance(i, sharing.SharedTemplate) for i in responses)


