def test_list_catalog_template_revisions_pager(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_catalog_template_revisions), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            catalog_management_messages.ListCatalogTemplateRevisionsResponse(
                catalog_template_revisions=[
                    catalog_management.CatalogTemplateRevision(),
                    catalog_management.CatalogTemplateRevision(),
                    catalog_management.CatalogTemplateRevision(),
                ],
                next_page_token="abc",
            ),
            catalog_management_messages.ListCatalogTemplateRevisionsResponse(
                catalog_template_revisions=[],
                next_page_token="def",
            ),
            catalog_management_messages.ListCatalogTemplateRevisionsResponse(
                catalog_template_revisions=[
                    catalog_management.CatalogTemplateRevision(),
                ],
                next_page_token="ghi",
            ),
            catalog_management_messages.ListCatalogTemplateRevisionsResponse(
                catalog_template_revisions=[
                    catalog_management.CatalogTemplateRevision(),
                    catalog_management.CatalogTemplateRevision(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_catalog_template_revisions(
            request={}, retry=retry, timeout=timeout
        )

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(
            isinstance(i, catalog_management.CatalogTemplateRevision) for i in results
        )


