def test_fetch_frameworks_pager(transport_name: str = "grpc"):
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.fetch_frameworks), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            best_practices_messages.FetchFrameworksResponse(
                frameworks=[
                    assessment.Framework(),
                    assessment.Framework(),
                    assessment.Framework(),
                ],
                next_page_token="abc",
            ),
            best_practices_messages.FetchFrameworksResponse(
                frameworks=[],
                next_page_token="def",
            ),
            best_practices_messages.FetchFrameworksResponse(
                frameworks=[
                    assessment.Framework(),
                ],
                next_page_token="ghi",
            ),
            best_practices_messages.FetchFrameworksResponse(
                frameworks=[
                    assessment.Framework(),
                    assessment.Framework(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.fetch_frameworks(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, assessment.Framework) for i in results)


