@pytest.mark.parametrize("null_interceptor", [True, False])
def test_create_application_template_rest_interceptors(null_interceptor):
    transport = transports.DesignCenterRestTransport(
        credentials=ga_credentials.AnonymousCredentials(),
        interceptor=None
        if null_interceptor
        else transports.DesignCenterRestInterceptor(),
    )
    client = DesignCenterClient(transport=transport)

    with (
        mock.patch.object(type(client.transport._session), "request") as req,
        mock.patch.object(path_template, "transcode") as transcode,
        mock.patch.object(
            transports.DesignCenterRestInterceptor, "post_create_application_template"
        ) as post,
        mock.patch.object(
            transports.DesignCenterRestInterceptor,
            "post_create_application_template_with_metadata",
        ) as post_with_metadata,
        mock.patch.object(
            transports.DesignCenterRestInterceptor, "pre_create_application_template"
        ) as pre,
    ):
        pre.assert_not_called()
        post.assert_not_called()
        post_with_metadata.assert_not_called()
        pb_message = authoring_messages.CreateApplicationTemplateRequest.pb(
            authoring_messages.CreateApplicationTemplateRequest()
        )
        transcode.return_value = {
            "method": "post",
            "uri": "my_uri",
            "body": pb_message,
            "query_params": pb_message,
        }

        req.return_value = mock.Mock()
        req.return_value.status_code = 200
        req.return_value.headers = {"header-1": "value-1", "header-2": "value-2"}
        return_value = authoring.ApplicationTemplate.to_json(
            authoring.ApplicationTemplate()
        )
        req.return_value.content = return_value

        request = authoring_messages.CreateApplicationTemplateRequest()
        metadata = [
            ("key", "val"),
            ("cephalopod", "squid"),
        ]
        pre.return_value = request, metadata
        post.return_value = authoring.ApplicationTemplate()
        post_with_metadata.return_value = authoring.ApplicationTemplate(), metadata

        client.create_application_template(
            request,
            metadata=[
                ("key", "val"),
                ("cephalopod", "squid"),
            ],
        )

        pre.assert_called_once()
        post.assert_called_once()
        post_with_metadata.assert_called_once()


