def test_design_center_grpc_lro_client():
    client = DesignCenterClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport="grpc",
    )
    transport = client.transport

    # Ensure that we have a api-core operations client.
    assert isinstance(
        transport.operations_client,
        operations_v1.OperationsClient,
    )

    # Ensure that subsequent calls to the property send the exact same object.
    assert transport.operations_client is transport.operations_client


def test_design_center_grpc_lro_async_client():
    client = DesignCenterAsyncClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport="grpc_asyncio",
    )
    transport = client.transport

    # Ensure that we have a api-core operations client.
    assert isinstance(
        transport.operations_client,
        operations_v1.OperationsAsyncClient,
    )

    # Ensure that subsequent calls to the property send the exact same object.
    assert transport.operations_client is transport.operations_client


def test_application_path():
    project = "squid"
    location = "clam"
    space = "whelk"
    application = "octopus"
    expected = "projects/{project}/locations/{location}/spaces/{space}/applications/{application}".format(
        project=project,
        location=location,
        space=space,
        application=application,
    )
    actual = DesignCenterClient.application_path(project, location, space, application)
    assert expected == actual


def test_parse_application_path():
    expected = {
        "project": "oyster",
        "location": "nudibranch",
        "space": "cuttlefish",
        "application": "mussel",
    }
    path = DesignCenterClient.application_path(**expected)

    # Check that the path construction is reversible.
    actual = DesignCenterClient.parse_application_path(path)
    assert expected == actual


